    "DEL_FLAG" TINYINT DEFAULT 0 COMMENT '删除标志（0：正常 1：已删除）',
    "CREATE_BY" CHARACTER VARYING(64) COMMENT '创建者',
    "CREATE_TIME" TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    "UPDATE_BY" CHARACTER VARYING(64) COMMENT '更新者',
